<?php

# @autogenerated
declare(strict_types=1);

namespace Civi\Lughauth\Features\Document\Theme\Infrastructure\Driver\Rest;

use Psr\Http\Message\ResponseInterface;
use Psr\Http\Message\ServerRequestInterface;
use Throwable;
use OpenApi\Attributes as OA;
use Civi\Lughauth\Features\Document\Theme\Domain\Gateway\ThemeFilter;
use Civi\Lughauth\Features\Document\Theme\Domain\Gateway\ThemeCursor;
use Civi\Lughauth\Features\Document\Theme\Domain\ThemeAttributes;
use Civi\Lughauth\Shared\Observability\LoggerAwareTrait;
use Civi\Lughauth\Shared\Observability\TracerAwareTrait;
use Civi\Lughauth\Features\Document\Theme\Application\Usecase\List\ThemeListUsecase;
use Civi\Lughauth\Features\Access\Tenant\Domain\TenantRef;

class ThemeListController
{
    use LoggerAwareTrait;
    use TracerAwareTrait;

    public function __construct(
        private readonly ThemeListUsecase $listUsecase,
    ) {
    }
    #[OA\Get(
        path: "/api/document/theme",
        tags: ["Theme"],
        description:"Create",
        responses: [
        new OA\Response(response: 201, description: "Ok", content: new OA\JsonContent(type: "object", ref:"#/components/schemas/ThemeApiListDTO")),
        new OA\Response(response: 422, description: "Constraint error"),
    ]
    )
    ]
    public function list(ServerRequestInterface $request, ResponseInterface $response, array $args): ResponseInterface
    {
        $this->logDebug("List Theme");
        $span = $this->startSpan("List Theme");
        try {
            $params = $request->getQueryParams();
            $filter = new ThemeFilter(
                uids: isset($params['uid']) ? [$params['uid']] : (isset($params['uids']) ? explode(',', $params['uids']) : null),
                search: $params['search'] ?? null,
                name: $params['name'] ?? null,
                tenant: isset($params['tenant']) ? new TenantRef($params['tenant']) : null,
                tenants: isset($params['tenants']) ? explode(",", $params['tenants']) : null,
            );
            $cursor = new ThemeCursor(
                limit: (int)($params['limit'] ?? 100),
                sinceUid: $params['since-uid'] ?? null,
                sinceName: $params['since-name'] ?? null,
                order: isset($params['order']) ? $this->extractOrder(explode(',', $params['order'])) : null,
            );
            $result = $this->listUsecase->list($filter, $cursor);
            $value = ['items' => array_map(fn (ThemeAttributes $item): ThemeApiDTO => $this->mapTheme($request, $item), $result->values())];
            $nextLink = $this->nextLink($result->cursor(), $params);
            if (null !== $nextLink) {
                $value['next'] = "?{$nextLink}";
            }
            $encoded = json_encode($value);
            $response->getBody()->write($encoded === false ? '' : $encoded);
            return $response->withStatus(200)
              ->withHeader('Content-Type', 'application/json');
        } catch (Throwable $ex) {
            $span->recordException($ex);
            throw $ex;
        } finally {
            $span->end();
        }
    }
    private function extractOrder(array $order): array
    {
        $this->logDebug("Extract order for Theme");
        $span = $this->startSpan("Extract order for Theme");
        try {
            $mapped = [];
            foreach ($order as $ord) {
                if ($ord === 'name-asc') {
                    $mapped[] = 'nameAsc';
                }
                if ($ord === 'name-desc') {
                    $mapped[] = 'nameDesc';
                }
            }
            return $mapped;
        } catch (Throwable $ex) {
            $span->recordException($ex);
            throw $ex;
        } finally {
            $span->end();
        }
    }
    private function nextLink(?ThemeCursor $value, array $params): ?string
    {
        $this->logDebug("Check generic allow for Theme");
        $span = $this->startSpan("Generic allow for Theme");
        try {
            if (!$value) {
                return null;
            }
            $link = [];
            if (isset($params['limit'])) {
                $link['limit'] = 'limit=' . $params['limit'];
            }
            $sinceUid = $value->sinceUid();
            if (null !== $sinceUid) {
                $link['since-uid'] = 'since-uid=' . urlencode($sinceUid);
            }
            $sinceName = $value->sinceName();
            if (null !== $sinceName &&  false !== strpos($params['order'] ?? '', 'NAME-ASC')) {
                $link['since-name'] = 'since-name=' . urlencode($sinceName);
            }
            $sinceName = $value->sinceName();
            if (null !== $sinceName &&  false !== strpos($params['order'] ?? '', 'NAME-DESC')) {
                $link['since-name'] = 'since-name=' . urlencode($sinceName);
            }
            return implode('&', $link);
        } catch (Throwable $ex) {
            $span->recordException($ex);
            throw $ex;
        } finally {
            $span->end();
        }
    }

    private function mapTheme(ServerRequestInterface $request, ThemeAttributes $value): ThemeApiDTO
    {
        $this->logDebug("Map entity to output dto for Theme");
        $span = $this->startSpan("Map entity to output dto for Theme");
        try {
            $tenant = $value->getTenant();
            $dto = new ThemeApiDTO();
            $dto->uid = $value->getUid();
            $dto->tenant = $tenant ? ['$ref' => $tenant->uid()] : null;
            $dto->name = $value->getName();
            $dto->isDefault = $value->isIsDefault();
            $dto->enabled = $value->isEnabled();
            $dto->customCss = $value->getCustomCss();
            $dto->version = $value->getVersion();
            return $dto;
        } catch (Throwable $ex) {
            $span->recordException($ex);
            throw $ex;
        } finally {
            $span->end();
        }
    }
}
